def getHappyString(n: int, k: int) -> str:
    if n == 1:
        return 'abc'[k-1] if k <= 3 else ''
    total = 3 * (1 << (n-2))
    if k > 3 * total:
        return ''
    third = (k-1) // total + 1
    rem = (k-1) % total + 1
    base = 'abc'[third-1]
    chars = 'abc'
    res = [base]
    for _ in range(n-1):
        for c in chars:
            if c != res[-1]:
                break
        chars = 'abc' if res[-1] == 'c' else 'abc'.replace(res[-1], '', 1)
        res.append(c)
        rem -= 1
        if rem == 0:
            break
    return ''.join(res)
